<?php require_once dirname(__DIR__).'/includes/functions.php';require_admin();if(($_GET['export']??'')==='csv'){header('Content-Type:text/csv');header('Content-Disposition:attachment; filename=recommendations.csv');$o=fopen('php://output','w');fputcsv($o,['Student','Email','Career','Match','Based on','Generated']);foreach($con->query('SELECT u.name,u.email,c.title,r.match_score,r.based_on,r.generated_at FROM career_recommendations r JOIN users u ON u.id=r.user_id JOIN careers c ON c.id=r.career_id ORDER BY r.generated_at DESC') as $r)fputcsv($o,$r);exit;}$rows=$con->query('SELECT u.name,u.email,c.title,r.match_score,r.based_on,r.generated_at FROM career_recommendations r JOIN users u ON u.id=r.user_id JOIN careers c ON c.id=r.career_id ORDER BY r.generated_at DESC LIMIT 300');$pageTitle='Recommendations';require __DIR__.'/includes/header.php';?><div class="d-flex justify-content-between"><div><h1 class="h3">Recommendation oversight</h1><p class="text-muted">Read-only generated career matches.</p></div><a class="btn btn-outline-primary align-self-start" href="?export=csv">Export CSV</a></div><div class="card table-responsive"><table class="table mb-0"><thead><tr><th>Student</th><th>Career</th><th>Match</th><th>Basis</th><th>Generated</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['name'])?><div class="small text-muted"><?=e($r['email'])?></div></td><td><?=e($r['title'])?></td><td><?=round($r['match_score'])?>%</td><td><?=e($r['based_on'])?></td><td><?=e($r['generated_at'])?></td></tr><?php endforeach?></tbody></table></div><?php require __DIR__.'/includes/footer.php';?>
